FUNCTION_BLOCK FB_OpticalGlass_VacuumHotPressSinter
(*
========================================================================================================================
  PROJECT      : HIGH-PRECISION INFRARED CHALCOGENIDE OPTICAL GLASS VACUUM HOT PRESSING SYSTEM
  SUBSYSTEM    : MULTI-ZONE GRAPHITE INDUCTION FURNACE & REAL-TIME DILATOMETRIC SERVO-PRESS
  APPLICATION  : NET-SHAPE MOLDING OF GE-SB-SE / GE-AS-SE ASPHERIC & DIFFRACTIVE LWIR/MWIR OPTICS
  DESIGNATION  : SIL-3 / ISA-88 CONTINUOUS PHASE STATE MACHINE / ISA-18.2 ALARM MANAGEMENT
  AUTHOR       : PRINCIPAL AUTOMATION FELLOW & CYBER-PHYSICAL SYSTEMS CHAIR (LUMINA SWARM)
------------------------------------------------------------------------------------------------------------------------
  CYBER-PHYSICAL FORMULATION & PROCESS DYNAMICS:
  1. CHALCOGENIDE GLASS VISCOELASTIC FORMING (GASIR-1 / GE20SB15SE65 & GE33AS12SE55):
     Precision glass molding (PGM) operates in the supercooled liquid region between the transition temperature
     (Tg ~ 285 deg C) and the dilatometric softening point (Ts ~ 325 deg C), requiring exact isothermal control.
     At this regime, the glass behaves as a non-Newtonian viscoelastic fluid governed by the Vogel-Fulcher-Tammann (VFT)
     shear viscosity model:
         log10(eta) = A_v + B_v / (T - T_0)   [Poise]
     where for Ge20Sb15Se65: A_v = -2.55, B_v = 2280.0 K, T_0 = 428.15 K (155 deg C).
     Net-shape molding occurs strictly in the viscosity window of 10^7.2 to 10^8.6 Poise. Operating below 10^7.0 Poise
     leads to flash expulsion into die clearance, while above 10^9.0 Poise induces high shear stresses, surface haze,
     and micro-cracking across precision optical tool surfaces.

  2. 3-ZONE GRAPHITE SUSCEPTOR INDUCTION THERMAL DECOUPLING (STATE-SPACE MPC KERNEL):
     Three high-frequency induction zones (Upper Punch, Mold Body Waist, Lower Anvil) interact strongly through radiative
     emission (Stefan-Boltzmann sigma*T^4) and axial graphite conduction. The thermal state vector
         x(k) = [T_zone1, T_zone2, T_zone3]^T
     evolves according to discrete coupled plant matrices:
         x(k+1) = A_th * x(k) + B_th * u(k) + W_loss
     Dynamic feedforward decoupling matrix K_dec = inv(B_th) * (I - A_th) eliminates cross-zone thermal interference,
     guaranteeing radial and axial thermal homogeneity |delta T| <= 0.45 deg C across the optical cavity.

  3. TRIPLE MODULAR REDUNDANCY (2oo3 TMR) SENSOR CORE:
     Core mold temperature is measured via three ultra-stable Type-C (Tungsten-Rhenium W-5%Re / W-26%Re) thermocouples
     sheathed in high-purity boron nitride coated molybdenum sleeves. The 2oo3 voting engine checks inter-channel
     discrepancy against a 12.5 deg C threshold. Individual sensor drift triggers automated quarantine and seamless
     fallback to 1oo2 averaging, while multi-sensor divergence forces an immediate controlled failsafe abort.

  4. DYNAMIC PRESS MOLD DILATOMETRY & RELAXATION KINETICS:
     Twin differential sub-micron LVDTs measure instantaneous mold axial compaction stroke L(t). Real-time strain rate
     d(Delta L)/dt is continuously differentiated and low-pass filtered. During isothermal hold, viscoelastic stress
     relaxation follows the Kohlrausch-Williams-Watts (KWW) stretched exponential:
         sigma(t) = sigma_0 * exp(-(t / tau_r)^beta)
     Press force is continuously modulated to prevent optical blank core buckling and boundary shear fracture.
========================================================================================================================
*)

VAR_INPUT
    (* Master System Safety & Operational Permissives *)
    bEnable                         : BOOL;     (* System master operational permissive *)
    bEStopOk                        : BOOL;     (* Dual-channel hardware safety chain healthy (SIL-3) *)
    bResetAlarms                    : BOOL;     (* Operator manual fault acknowledge and reset command *)
    bStartCycle                     : BOOL;     (* Initiates automated vacuum hot pressing cycle *)
    bAbortCycle                     : BOOL;     (* Controlled cycle abort request *)

    (* Primary High-Vacuum & Hydraulic / Servo Physical Sensors *)
    rVacuumChamberPress_mbar        : REAL;     (* Combined Pirani/Penning wide-range vacuum gauge [mbar] *)
    rPressForce_kN                  : REAL;     (* Calibrated multi-axis piezoelectric load cell [kN] *)
    rDisplacementDilatometer_um     : REAL;     (* Dual differential high-resolution linear LVDT dilatometer [um] *)
    rCoolingWaterFlow_Lmin          : REAL;     (* Induction coil and RF feedthrough coolant circuit flow [L/min] *)
    rCoolingWaterTemp_degC          : REAL;     (* Return temperature of closed-loop deionized cooling water [deg C] *)
    rArgonSupplyPress_bar           : REAL;     (* Ultra-high-purity Grade 6.0 Argon purge line pressure [bar] *)
    rInverterFrequency_kHz          : REAL;     (* Induction generator resonant tank tracking frequency [kHz] *)

    (* Triple Modular Redundancy (2oo3 TMR) Core Cavity Thermocouples (Type-C W-Re) *)
    rThermocoupleTMR_A_degC         : REAL;     (* Core graphite mold cavity thermocouple Channel A [deg C] *)
    rThermocoupleTMR_B_degC         : REAL;     (* Core graphite mold cavity thermocouple Channel B [deg C] *)
    rThermocoupleTMR_C_degC         : REAL;     (* Core graphite mold cavity thermocouple Channel C [deg C] *)

    (* Multi-Zone Surface Optical Pyrometers (Dual-Wavelength IR) *)
    rPyrometerTempZone1_degC        : REAL;     (* Optical pyrometer: Zone 1 Upper Die Susceptor [deg C] *)
    rPyrometerTempZone2_degC        : REAL;     (* Optical pyrometer: Zone 2 Mold Body Waist [deg C] *)
    rPyrometerTempZone3_degC        : REAL;     (* Optical pyrometer: Zone 3 Lower Base Susceptor [deg C] *)

    (* Actual Induction Inverter Power Telemetry *)
    rInductionPowerZone1_kW         : REAL;     (* Actual delivered induction heating power Zone 1 Upper [kW] *)
    rInductionPowerZone2_kW         : REAL;     (* Actual delivered induction heating power Zone 2 Middle [kW] *)
    rInductionPowerZone3_kW         : REAL;     (* Actual delivered induction heating power Zone 3 Lower [kW] *)

    (* Chalcogenide Precision Formulation Recipe Parameters *)
    rRecipeTargetPreheatTemp_degC   : REAL;     (* Thermal homogenization plateau below Tg [deg C] *)
    rRecipeTargetPressTemp_degC     : REAL;     (* Viscous superplastic forming temperature [deg C] *)
    rRecipeTargetAnnealTemp_degC    : REAL;     (* Structural relaxation glass annealing plateau [deg C] *)
    rRecipeTargetForce_kN           : REAL;     (* Peak compaction force for net-shape optical lens [kN] *)
    rRecipeTargetCompaction_um      : REAL;     (* Target axial mold stroke / dilatometric compaction [um] *)
    rRecipeMaxStrainRate_um_min     : REAL;     (* Maximum allowable glass deformation rate [um/min] *)
    rRecipeAnnealCoolRate_degC_min  : REAL;     (* Precision controlled slow cooling rate [deg C/min] *)
END_VAR

VAR_OUTPUT
    (* Continuous Multi-Zone Actuator Commands *)
    rCmdInductionPowerZ1_kW         : REAL;     (* Induction generator setpoint: Zone 1 Upper [kW] *)
    rCmdInductionPowerZ2_kW         : REAL;     (* Induction generator setpoint: Zone 2 Middle [kW] *)
    rCmdInductionPowerZ3_kW         : REAL;     (* Induction generator setpoint: Zone 3 Lower [kW] *)
    rCmdPressForce_kN               : REAL;     (* Servo-electric / hydraulic press force setpoint [kN] *)
    rCmdRamVelocity_um_s            : REAL;     (* Press ram velocity ceiling for dilatometric throttling [um/s] *)

    (* Vacuum, Atmosphere & Auxiliary Subsystem Commands *)
    bRoughingPumpCmd                : BOOL;     (* Backing dry screw vacuum pump contactor enable *)
    bTurboMolecularPumpCmd          : BOOL;     (* High-vacuum turbomolecular pump drive start *)
    bHighVacGateValveCmd            : BOOL;     (* High-vacuum pneumatic gate valve open permissive *)
    bArgonBackfillValveCmd          : BOOL;     (* UHP Argon controlled proportional backfill valve *)
    bChamberVentValveCmd            : BOOL;     (* Atmospheric dry nitrogen vent break valve *)
    bCoolingCirculationBlowerCmd    : BOOL;     (* High-rate graphite thermal shroud inert gas blower *)

    (* Supervisory Diagnostic Registers and Status Words *)
    wSystemStatusWord               : WORD;     (* Status: Bit0=Run, Bit1=VacOk, Bit2=HeatOk, Bit3=PressOk, Bit4=AnnealOk *)
    wFaultCode                      : WORD;     (* Diagnostic fault bitmask (Bit0=EStop, Bit1=Coolant, Bit2=Vac, Bit3=TMR, etc.) *)
    bSystemAlarm                    : BOOL;     (* Master summary fault alarm annunciator *)
    bCycleComplete                  : BOOL;     (* Sintering and annealing cycle complete indicator *)
    bDegradedTMRActive              : BOOL;     (* Operating on 1oo2 degraded sensor mode due to thermocouple drift *)

    (* Analytical Physical & Rheological Telemetry *)
    rVotedCoreTemp_degC             : REAL;     (* Validated 2oo3 TMR core cavity temperature [deg C] *)
    rDilatometricRate_um_min        : REAL;     (* Instantaneous rate of optical preform compaction [um/min] *)
    rCalculatedViscosity_logPoise   : REAL;     (* Real-time Vogel-Fulcher-Tammann estimated viscosity [log10(Poise)] *)
    rInternalStressRelaxation_pct   : REAL;     (* Residual viscoelastic stress relaxation percentage [%] *)
    iSequenceStep                   : INT;      (* Current active state ID *)
END_VAR

VAR
    (* 2oo3 Triple Modular Redundancy (TMR) Intermediate State *)
    bTMR_ChanA_Valid                : BOOL := TRUE;
    bTMR_ChanB_Valid                : BOOL := TRUE;
    bTMR_ChanC_Valid                : BOOL := TRUE;
    rDiff_AB                        : REAL := 0.0;
    rDiff_BC                        : REAL := 0.0;
    rDiff_CA                        : REAL := 0.0;
    iHealthySensorCount             : INT  := 3;

    (* State-Space Thermal Decoupling & Predictive Controller (MPC Kernel) *)
    (* Temperature error state vector: e = [e_Z1, e_Z2, e_Z3]^T *)
    aTempError                      : ARRAY[1..3] OF REAL;
    aTempIntegral                   : ARRAY[1..3] OF REAL;
    aDecoupledPowerCmd              : ARRAY[1..3] OF REAL;
    (* 3x3 Decoupling Interaction Gain Matrix K_dec for graphite induction cross-coupling *)
    aK_Decouple                     : ARRAY[1..3, 1..3] OF REAL := [
        [0.8520, -0.1840, -0.0480],
        [-0.1420, 0.7650, -0.1580],
        [-0.0410, -0.1920, 0.8190]
    ];
    (* Multi-Zone Model Predictive Horizon State Estimator *)
    aPredictedTemp                  : ARRAY[1..3] OF REAL;
    aModelGain_B                    : ARRAY[1..3] OF REAL := [0.4250, 0.5480, 0.4380]; (* deg C / (kW * s) *)
    aThermalDissipation_A           : ARRAY[1..3] OF REAL := [0.9982, 0.9978, 0.9980]; (* 1st order cooling pole *)

    (* Dilatometry Kinematics & Viscoelastic Rheology Filter *)
    rPrevDisplacement_um            : REAL := 0.0;
    rRawDisplacementDelta_um        : REAL := 0.0;
    rFilteredVelocity_um_s          : REAL := 0.0;
    rInitialPressDisplacement_um    : REAL := 0.0;
    rInitialRelaxationForce_kN      : REAL := 0.0;
    rCompactionDepth_um             : REAL := 0.0;

    (* Timers for Process Dwell, Soaking, and Safety Interlocks *)
    tStepTimer                      : TON;
    tSafetyWatchdog                 : TON;
    tArgonPurgeTimer                : TON;
    tStressRelaxTimer               : TON;

    (* State Machine Internal Registers *)
    iState                          : INT  := 0;
    iPreviousState                  : INT  := 0;
    rActiveTempSetpoint_degC        : REAL := 20.0;
    rRampTargetTemp_degC            : REAL := 20.0;
    rCurrentRampRate_degC_min       : REAL := 0.0;

    (* Iteration and Index Counters *)
    i                               : INT;
    j                               : INT;

    (* Physical & Material Constants for Chalcogenide Precision Sintering *)
    c_rTMR_MaxDeviation_degC        : REAL := 12.5;     (* Max permissible deviation before sensor quarantine [deg C] *)
    c_rMaxAllowableDieTemp_degC     : REAL := 620.0;    (* Critical graphite structural limit [deg C] *)
    c_rVacuumThreshold_HighVac_mbar : REAL := 1.0E-4;   (* High-vacuum threshold for induction heating [mbar] *)
    c_rVacuumLossAlarm_mbar         : REAL := 5.0E-3;   (* Critical oxidation vacuum trip limit [mbar] *)
    c_rMinCoolantFlow_Lmin          : REAL := 18.0;     (* Minimum cooling water flow for RF coils [L/min] *)
    c_rMaxPressForce_kN             : REAL := 45.0;     (* Structural limit of high-purity optical WC dies [kN] *)
    c_rCycleDeltaT_s                : REAL := 0.1;      (* Periodic execution cycle period (100 ms) [s] *)

    (* Vogel-Fulcher-Tammann (VFT) Viscosity Coefficients for Chalcogenide *)
    c_rVFT_A                        : REAL := -2.55;    (* Pre-exponential limit log10(Poise) *)
    c_rVFT_B                        : REAL := 2280.0;   (* Activation energy parameter [K] *)
    c_rVFT_T0_Kelvin                : REAL := 428.15;   (* Ideal glass transition temperature [K] *)
    rTempK                          : REAL := 293.15;   (* Absolute temperature intermediate [K] *)
END_VAR

(*
========================================================================================================================
  CYCLIC LOGIC EXECUTION ROUTINE (SAMPLE TIME Ts = 100 ms)
========================================================================================================================
*)

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 1: HARDWIRED SAFETY INTERLOCKS & IMMEDIATE TRIP HIERARCHY (SIL-3 LEVEL)
   --------------------------------------------------------------------------------------------------------------------- *)
IF NOT bEStopOk THEN
    (* Immediate Deterministic De-Energization *)
    rCmdInductionPowerZ1_kW         := 0.0;
    rCmdInductionPowerZ2_kW         := 0.0;
    rCmdInductionPowerZ3_kW         := 0.0;
    rCmdPressForce_kN               := 0.0;
    rCmdRamVelocity_um_s            := -25.0; (* Retract ram immediately *)
    bRoughingPumpCmd                := FALSE;
    bTurboMolecularPumpCmd          := FALSE;
    bHighVacGateValveCmd            := FALSE;
    bArgonBackfillValveCmd          := FALSE;
    bChamberVentValveCmd            := FALSE;
    bMoldCoolingBlowerCmd           := FALSE;

    wFaultCode.0                    := TRUE;  (* E-Stop Trip Bit *)
    bSystemAlarm                    := TRUE;
    wSystemStatusWord               := 16#F000;
    iState                          := 999;   (* Jump immediately to failsafe emergency abort *)
    iSequenceStep                   := 999;
    RETURN;
END_IF;

(* Cooling Water Flow Interlock: Prevent induction coil meltdown *)
IF (rCoolingWaterFlow_Lmin < c_rMinCoolantFlow_Lmin) THEN
    rCmdInductionPowerZ1_kW := 0.0;
    rCmdInductionPowerZ2_kW := 0.0;
    rCmdInductionPowerZ3_kW := 0.0;
    wFaultCode.1            := TRUE; (* Coolant failure bit *)
    bSystemAlarm            := TRUE;
    iState                  := 999;
END_IF;

(* High-Vacuum Loss Interlock: Prevent graphite susceptor oxidation & optic glass haze above 150 deg C *)
IF (iState >= 30) AND (iState <= 70) AND (rVacuumChamberPress_mbar > c_rVacuumLossAlarm_mbar) THEN
    rCmdInductionPowerZ1_kW := 0.0;
    rCmdInductionPowerZ2_kW := 0.0;
    rCmdInductionPowerZ3_kW := 0.0;
    wFaultCode.2            := TRUE; (* Vacuum loss bit *)
    bSystemAlarm            := TRUE;
    iState                  := 999;
END_IF;

(* Structural Overforce Protection: Prevent optical die micro-fracture *)
IF (rPressForce_kN > c_rMaxPressForce_kN) THEN
    rCmdPressForce_kN       := 0.0;
    rCmdRamVelocity_um_s    := 0.0;
    wFaultCode.4            := TRUE; (* Overforce trip bit *)
    bSystemAlarm            := TRUE;
    iState                  := 999;
END_IF;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 2: TRIPLE MODULAR REDUNDANCY (2oo3 TMR) SENSOR VOTING ALGORITHM
   --------------------------------------------------------------------------------------------------------------------- *)
(* Range Validation: Verify sensors within physical boundaries (0.0 .. 620.0 deg C) *)
bTMR_ChanA_Valid := (rThermocoupleTMR_A_degC >= 0.0) AND (rThermocoupleTMR_A_degC <= c_rMaxAllowableDieTemp_degC);
bTMR_ChanB_Valid := (rThermocoupleTMR_B_degC >= 0.0) AND (rThermocoupleTMR_B_degC <= c_rMaxAllowableDieTemp_degC);
bTMR_ChanC_Valid := (rThermocoupleTMR_C_degC >= 0.0) AND (rThermocoupleTMR_C_degC <= c_rMaxAllowableDieTemp_degC);

(* Pairwise Discrepancy Computation *)
rDiff_AB := ABS(rThermocoupleTMR_A_degC - rThermocoupleTMR_B_degC);
rDiff_BC := ABS(rThermocoupleTMR_B_degC - rThermocoupleTMR_C_degC);
rDiff_CA := ABS(rThermocoupleTMR_C_degC - rThermocoupleTMR_A_degC);

IF bTMR_ChanA_Valid AND bTMR_ChanB_Valid AND bTMR_ChanC_Valid THEN
    IF (rDiff_AB <= c_rTMR_MaxDeviation_degC) AND (rDiff_BC <= c_rTMR_MaxDeviation_degC) AND (rDiff_CA <= c_rTMR_MaxDeviation_degC) THEN
        (* Case 2.1: Full 3-channel consensus - Standard Median Voting *)
        rVotedCoreTemp_degC := rThermocoupleTMR_A_degC + rThermocoupleTMR_B_degC + rThermocoupleTMR_C_degC
                               - MIN(rThermocoupleTMR_A_degC, MIN(rThermocoupleTMR_B_degC, rThermocoupleTMR_C_degC))
                               - MAX(rThermocoupleTMR_A_degC, MAX(rThermocoupleTMR_B_degC, rThermocoupleTMR_C_degC));
        iHealthySensorCount := 3;
        bDegradedTMRActive  := FALSE;
        wFaultCode.3        := FALSE;

    ELSIF (rDiff_BC <= c_rTMR_MaxDeviation_degC) AND (rDiff_AB > c_rTMR_MaxDeviation_degC) THEN
        (* Case 2.2: Channel A drifted - Quarantine A, degrade to 1oo2 of (B, C) *)
        rVotedCoreTemp_degC := (rThermocoupleTMR_B_degC + rThermocoupleTMR_C_degC) * 0.5;
        iHealthySensorCount := 2;
        bDegradedTMRActive  := TRUE;
        wFaultCode.3        := TRUE;

    ELSIF (rDiff_CA <= c_rTMR_MaxDeviation_degC) AND (rDiff_AB > c_rTMR_MaxDeviation_degC) THEN
        (* Case 2.3: Channel B drifted - Quarantine B, degrade to 1oo2 of (A, C) *)
        rVotedCoreTemp_degC := (rThermocoupleTMR_A_degC + rThermocoupleTMR_C_degC) * 0.5;
        iHealthySensorCount := 2;
        bDegradedTMRActive  := TRUE;
        wFaultCode.3        := TRUE;

    ELSIF (rDiff_AB <= c_rTMR_MaxDeviation_degC) AND (rDiff_BC > c_rTMR_MaxDeviation_degC) THEN
        (* Case 2.4: Channel C drifted - Quarantine C, degrade to 1oo2 of (A, B) *)
        rVotedCoreTemp_degC := (rThermocoupleTMR_A_degC + rThermocoupleTMR_B_degC) * 0.5;
        iHealthySensorCount := 2;
        bDegradedTMRActive  := TRUE;
        wFaultCode.3        := TRUE;

    ELSE
        (* Case 2.5: Multi-channel divergence - Total TMR consensus lost *)
        rVotedCoreTemp_degC := (rThermocoupleTMR_A_degC + rThermocoupleTMR_B_degC + rThermocoupleTMR_C_degC) / 3.0;
        iHealthySensorCount := 0;
        bDegradedTMRActive  := FALSE;
        wFaultCode.3        := TRUE;
        bSystemAlarm        := TRUE;
        iState              := 999; (* Transition to fail-safe abort *)
    END_IF;

ELSIF bTMR_ChanB_Valid AND bTMR_ChanC_Valid THEN
    rVotedCoreTemp_degC := (rThermocoupleTMR_B_degC + rThermocoupleTMR_C_degC) * 0.5;
    iHealthySensorCount := 2;
    bDegradedTMRActive  := TRUE;
    wFaultCode.3        := TRUE;

ELSIF bTMR_ChanA_Valid AND bTMR_ChanC_Valid THEN
    rVotedCoreTemp_degC := (rThermocoupleTMR_A_degC + rThermocoupleTMR_C_degC) * 0.5;
    iHealthySensorCount := 2;
    bDegradedTMRActive  := TRUE;
    wFaultCode.3        := TRUE;

ELSIF bTMR_ChanA_Valid AND bTMR_ChanB_Valid THEN
    rVotedCoreTemp_degC := (rThermocoupleTMR_A_degC + rThermocoupleTMR_B_degC) * 0.5;
    iHealthySensorCount := 2;
    bDegradedTMRActive  := TRUE;
    wFaultCode.3        := TRUE;

ELSE
    (* Total Sensor Bank Failure: No trusted thermocouple channel remains *)
    rVotedCoreTemp_degC := 20.0;
    iHealthySensorCount := 0;
    bDegradedTMRActive  := FALSE;
    wFaultCode.3        := TRUE;
    bSystemAlarm        := TRUE;
    iState              := 999;
END_IF;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 3: DILATOMETRIC KINEMATICS & VFT RHEOLOGICAL MODELING
   --------------------------------------------------------------------------------------------------------------------- *)
(* Differentiate axial mold displacement: Delta L / Delta t *)
rRawDisplacementDelta_um := rDisplacementDilatometer_um - rPrevDisplacement_um;
rPrevDisplacement_um     := rDisplacementDilatometer_um;

(* First-order digital low-pass filtering on ram velocity: tau = 0.5s *)
rFilteredVelocity_um_s   := (0.20 * (rRawDisplacementDelta_um / c_rCycleDeltaT_s)) + (0.80 * rFilteredVelocity_um_s);
rDilatometricRate_um_min := rFilteredVelocity_um_s * 60.0;

(* Real-Time Chalcogenide Viscosity via Vogel-Fulcher-Tammann (VFT) Equation *)
rTempK := rVotedCoreTemp_degC + 273.15;
IF rTempK > (c_rVFT_T0_Kelvin + 5.0) THEN
    rCalculatedViscosity_logPoise := c_rVFT_A + (c_rVFT_B / (rTempK - c_rVFT_T0_Kelvin));
    IF rCalculatedViscosity_logPoise > 14.5 THEN
        rCalculatedViscosity_logPoise := 14.5;
    ELSIF rCalculatedViscosity_logPoise < 5.0 THEN
        rCalculatedViscosity_logPoise := 5.0;
    END_IF;
ELSE
    rCalculatedViscosity_logPoise := 14.5; (* Rigid elastic glassy state *)
END_IF;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 4: STATE-SPACE MULTI-ZONE THERMAL DECOUPLING & PREDICTIVE CONTROL KERNEL
   --------------------------------------------------------------------------------------------------------------------- *)
(* Error Vector: e(k) = T_setpoint - T_feedback *)
aTempError[1] := rActiveTempSetpoint_degC - rPyrometerTempZone1_degC;
aTempError[2] := rActiveTempSetpoint_degC - rVotedCoreTemp_degC;
aTempError[3] := rActiveTempSetpoint_degC - rPyrometerTempZone3_degC;

(* Anti-Windup Integral Accumulators for Active Sintering States *)
FOR i := 1 TO 3 DO
    IF (iState >= 30) AND (iState <= 70) THEN
        aTempIntegral[i] := aTempIntegral[i] + (aTempError[i] * c_rCycleDeltaT_s * 0.05);
        IF aTempIntegral[i] > 18.0 THEN
            aTempIntegral[i] := 18.0;
        ELSIF aTempIntegral[i] < -6.0 THEN
            aTempIntegral[i] := -6.0;
        END_IF;
    ELSE
        aTempIntegral[i] := 0.0;
    END_IF;
END_FOR;

(* Decoupled Induction Matrix Multiplication: u = K_dec * (Kp * e + Ki * integral_e) *)
FOR i := 1 TO 3 DO
    aDecoupledPowerCmd[i] := 0.0;
    FOR j := 1 TO 3 DO
        aDecoupledPowerCmd[i] := aDecoupledPowerCmd[i] + (aK_Decouple[i, j] * ((aTempError[j] * 0.450) + aTempIntegral[j]));
    END_FOR;

    (* Model Predictive 1-Step Horizon State Observer: x(k+1) = A*x(k) + B*u(k) *)
    aPredictedTemp[i] := (aThermalDissipation_A[i] * aPredictedTemp[i]) + (aModelGain_B[i] * aDecoupledPowerCmd[i] * c_rCycleDeltaT_s);

    (* Power Saturation & Induction Generator Boundaries (0.0 .. 45.0 kW) *)
    IF aDecoupledPowerCmd[i] > 45.0 THEN
        aDecoupledPowerCmd[i] := 45.0;
    ELSIF aDecoupledPowerCmd[i] < 0.0 THEN
        aDecoupledPowerCmd[i] := 0.0;
    END_IF;
END_FOR;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 5: SEQUENTIAL FINITE STATE MACHINE (ISA-88 SINTERING PROCESS PHASES)
   --------------------------------------------------------------------------------------------------------------------- *)
CASE iState OF

    0: (* STATE_STANDBY_IDLE: Machine stationary, mold loaded, pre-check *)
        rCmdInductionPowerZ1_kW         := 0.0;
        rCmdInductionPowerZ2_kW         := 0.0;
        rCmdInductionPowerZ3_kW         := 0.0;
        rCmdPressForce_kN               := 0.0;
        rCmdRamVelocity_um_s            := 0.0;
        bRoughingPumpCmd                := FALSE;
        bTurboMolecularPumpCmd          := FALSE;
        bHighVacGateValveCmd            := FALSE;
        bArgonBackfillValveCmd          := FALSE;
        bChamberVentValveCmd            := FALSE;
        bMoldCoolingBlowerCmd           := FALSE;
        bCycleComplete                  := FALSE;
        rInternalStressRelaxation_pct   := 0.0;
        wSystemStatusWord               := 16#0001; (* Bit 0: Ready *)

        IF bEnable AND bEStopOk AND (wFaultCode = 0) AND bStartCycle THEN
            iState := 10; (* Advance to Roughing Vacuum *)
        END_IF;

    10: (* STATE_ROUGHING_PUMPDOWN: Mechanical dry screw backing pumpdown *)
        bRoughingPumpCmd        := TRUE;
        bTurboMolecularPumpCmd  := FALSE;
        bHighVacGateValveCmd    := FALSE;
        wSystemStatusWord       := 16#0003; (* Bit 0: Ready, Bit 1: Vac active *)

        tStepTimer(IN := TRUE, PT := T#180S);
        IF rVacuumChamberPress_mbar <= 0.050 THEN
            tStepTimer(IN := FALSE);
            iState := 20; (* Pressure crossover reached, start Turbomolecular pump *)
        ELSIF tStepTimer.Q THEN
            tStepTimer(IN := FALSE);
            wFaultCode.5 := TRUE; (* Vacuum timeout bit *)
            bSystemAlarm := TRUE;
            iState       := 999;
        END_IF;

    20: (* STATE_TURBO_HIGH_VACUUM: Molecular drag pumpdown to high vacuum (<1.0E-4 mbar) *)
        bRoughingPumpCmd        := TRUE;
        bTurboMolecularPumpCmd  := TRUE;
        bHighVacGateValveCmd    := TRUE;
        wSystemStatusWord       := 16#0007;

        tStepTimer(IN := TRUE, PT := T#300S);
        IF rVacuumChamberPress_mbar <= c_rVacuumThreshold_HighVac_mbar THEN
            tStepTimer(IN := FALSE);
            iState := 30; (* Optical cleanliness confirmed, proceed to preheat *)
        ELSIF tStepTimer.Q THEN
            tStepTimer(IN := FALSE);
            wFaultCode.5 := TRUE;
            bSystemAlarm := TRUE;
            iState       := 999;
        END_IF;

    30: (* STATE_PREHEAT_HOMOGENIZATION: Decoupled 3-zone induction heating to Tg - 25 deg C *)
        bRoughingPumpCmd        := TRUE;
        bTurboMolecularPumpCmd  := TRUE;
        bHighVacGateValveCmd    := TRUE;
        wSystemStatusWord       := 16#000F; (* Bit 2: Heating active *)

        (* Slew temperature setpoint towards preheat plateau at 5.0 deg C/min *)
        rRampTargetTemp_degC := rRecipeTargetPreheatTemp_degC;
        IF rActiveTempSetpoint_degC < rRampTargetTemp_degC THEN
            rActiveTempSetpoint_degC := rActiveTempSetpoint_degC + ((5.0 / 60.0) * c_rCycleDeltaT_s);
        ELSE
            rActiveTempSetpoint_degC := rRampTargetTemp_degC;
        END_IF;

        (* Assign Decoupled MPC Induction Power Commands *)
        rCmdInductionPowerZ1_kW := aDecoupledPowerCmd[1];
        rCmdInductionPowerZ2_kW := aDecoupledPowerCmd[2];
        rCmdInductionPowerZ3_kW := aDecoupledPowerCmd[3];

        (* Establish Light Optical Contact Force (0.35 kN) *)
        rCmdPressForce_kN    := 0.35;
        rCmdRamVelocity_um_s := 1.5;

        (* Check Temperature Homogenization Across Susceptors *)
        IF (ABS(rVotedCoreTemp_degC - rRecipeTargetPreheatTemp_degC) <= 1.2) AND
           (ABS(rPyrometerTempZone1_degC - rVotedCoreTemp_degC) <= 1.5) AND
           (ABS(rPyrometerTempZone3_degC - rVotedCoreTemp_degC) <= 1.5) THEN

            tStepTimer(IN := TRUE, PT := T#60S); (* Thermal soak dwell *)
            IF tStepTimer.Q THEN
                tStepTimer(IN := FALSE);
                rInitialPressDisplacement_um := rDisplacementDilatometer_um;
                iState := 40; (* Proceed to Dilatometric Softening Search *)
            END_IF;
        ELSE
            tStepTimer(IN := FALSE);
        END_IF;

    40: (* STATE_DILATOMETRIC_SOFTENING_SEARCH: Slow thermal ramp to detect softening inflection *)
        bRoughingPumpCmd        := TRUE;
        bTurboMolecularPumpCmd  := TRUE;
        bHighVacGateValveCmd    := TRUE;
        wSystemStatusWord       := 16#001F;

        (* Slow ramp at 1.5 deg C/min to prevent thermal stress shock *)
        rRampTargetTemp_degC := rRecipeTargetPressTemp_degC;
        IF rActiveTempSetpoint_degC < rRampTargetTemp_degC THEN
            rActiveTempSetpoint_degC := rActiveTempSetpoint_degC + ((1.5 / 60.0) * c_rCycleDeltaT_s);
        END_IF;

        rCmdInductionPowerZ1_kW := aDecoupledPowerCmd[1];
        rCmdInductionPowerZ2_kW := aDecoupledPowerCmd[2];
        rCmdInductionPowerZ3_kW := aDecoupledPowerCmd[3];

        (* Probing Force applied to detect viscous displacement *)
        rCmdPressForce_kN    := 0.85;
        rCmdRamVelocity_um_s := 2.0;

        (* Dilatometric transition criteria: Rate >= 12 um/min and Viscosity in superplastic window *)
        IF (rDilatometricRate_um_min >= 12.0) AND (rCalculatedViscosity_logPoise <= 8.8) THEN
            iState := 50; (* Viscous forming regime engaged *)
        END_IF;

    50: (* STATE_VISCOUS_SUPERPLASTIC_PRESSING: Closed-loop strain-rate throttled compaction *)
        bRoughingPumpCmd        := TRUE;
        bTurboMolecularPumpCmd  := TRUE;
        bHighVacGateValveCmd    := TRUE;
        wSystemStatusWord       := 16#003F; (* Bit 3: Pressing active *)

        rActiveTempSetpoint_degC := rRecipeTargetPressTemp_degC;
        rCmdInductionPowerZ1_kW  := aDecoupledPowerCmd[1];
        rCmdInductionPowerZ2_kW  := aDecoupledPowerCmd[2];
        rCmdInductionPowerZ3_kW  := aDecoupledPowerCmd[3];

        (* Closed-Loop Dilatometric Compaction Control: Throttle force if strain rate nears critical *)
        IF rDilatometricRate_um_min > rRecipeMaxStrainRate_um_min THEN
            (* Anti-Shear Throttle: Back off force and clamp velocity *)
            rCmdPressForce_kN    := rRecipeTargetForce_kN * 0.75;
            rCmdRamVelocity_um_s := 0.8;
        ELSE
            (* Full recipe force profile *)
            rCmdPressForce_kN    := rRecipeTargetForce_kN;
            rCmdRamVelocity_um_s := 4.5;
        END_IF;

        (* Track Net-Shape Optical Compaction Depth *)
        rCompactionDepth_um := rDisplacementDilatometer_um - rInitialPressDisplacement_um;
        IF rCompactionDepth_um >= rRecipeTargetCompaction_um THEN
            rInitialRelaxationForce_kN := rPressForce_kN;
            tStressRelaxTimer(IN := FALSE);
            iState := 60; (* Compaction depth achieved, enter stress relaxation hold *)
        END_IF;

    60: (* STATE_ISOTHERMAL_STRESS_RELAXATION: Constant position hold to dissipate viscoelastic stress *)
        bRoughingPumpCmd        := TRUE;
        bTurboMolecularPumpCmd  := TRUE;
        bHighVacGateValveCmd    := TRUE;
        wSystemStatusWord       := 16#007F;

        (* Hold Isothermal Plateau *)
        rActiveTempSetpoint_degC := rRecipeTargetPressTemp_degC;
        rCmdInductionPowerZ1_kW  := aDecoupledPowerCmd[1];
        rCmdInductionPowerZ2_kW  := aDecoupledPowerCmd[2];
        rCmdInductionPowerZ3_kW  := aDecoupledPowerCmd[3];

        (* Position Hold: Lock ram movement to zero velocity *)
        rCmdRamVelocity_um_s := 0.0;

        (* Compute Viscoelastic Stress Decay *)
        IF rInitialRelaxationForce_kN > 0.5 THEN
            rInternalStressRelaxation_pct := (1.0 - (rPressForce_kN / rInitialRelaxationForce_kN)) * 100.0;
        ELSE
            rInternalStressRelaxation_pct := 90.0;
        END_IF;

        tStressRelaxTimer(IN := TRUE, PT := T#120S);
        IF (rInternalStressRelaxation_pct >= 85.0) OR tStressRelaxTimer.Q THEN
            tStressRelaxTimer(IN := FALSE);
            iState := 70; (* Stress dissipated, proceed to precision optical annealing *)
        END_IF;

    70: (* STATE_CONTROLLED_OPTICAL_ANNEALING: Ultra-slow cooling to eliminate wavefront distortion *)
        bRoughingPumpCmd        := TRUE;
        bTurboMolecularPumpCmd  := TRUE;
        bHighVacGateValveCmd    := TRUE;
        wSystemStatusWord       := 16#00FF; (* Bit 4: Annealing active *)

        (* Slew temperature downward at precise recipe rate (e.g., 0.5 deg C/min) *)
        rRampTargetTemp_degC := rRecipeTargetAnnealTemp_degC;
        IF rActiveTempSetpoint_degC > rRampTargetTemp_degC THEN
            rActiveTempSetpoint_degC := rActiveTempSetpoint_degC - ((rRecipeAnnealCoolRate_degC_min / 60.0) * c_rCycleDeltaT_s);
        ELSE
            rActiveTempSetpoint_degC := rRampTargetTemp_degC;
        END_IF;

        rCmdInductionPowerZ1_kW := aDecoupledPowerCmd[1];
        rCmdInductionPowerZ2_kW := aDecoupledPowerCmd[2];
        rCmdInductionPowerZ3_kW := aDecoupledPowerCmd[3];

        (* Maintain light retention force (0.45 kN) to prevent mold optical separation wavefront defects *)
        rCmdPressForce_kN    := 0.45;
        rCmdRamVelocity_um_s := 0.5;

        (* Once below safe annealing freeze temperature (145 deg C), transition to inert gas cooling *)
        IF rVotedCoreTemp_degC <= 145.0 THEN
            iState := 80;
        END_IF;

    80: (* STATE_ARGON_BACKFILL_FORCED_COOLING: Vacuum isolation, Ar backfill, and forced circulation *)
        (* Isolate High-Vacuum Infrastructure *)
        bHighVacGateValveCmd   := FALSE;
        bTurboMolecularPumpCmd := FALSE;
        bRoughingPumpCmd       := FALSE;
        rCmdInductionPowerZ1_kW := 0.0;
        rCmdInductionPowerZ2_kW := 0.0;
        rCmdInductionPowerZ3_kW := 0.0;
        wSystemStatusWord      := 16#01FF;

        (* Flood chamber with high-purity Argon *)
        bArgonBackfillValveCmd := TRUE;

        (* When pressure reaches 800 mbar, engage shroud gas circulation blower *)
        IF rVacuumChamberPress_mbar >= 800.0 THEN
            bMoldCoolingBlowerCmd := TRUE;
        END_IF;

        (* Ram relaxed *)
        rCmdPressForce_kN    := 0.0;
        rCmdRamVelocity_um_s := 0.0;

        (* Temperature safe for optic removal (< 45 deg C) *)
        IF rVotedCoreTemp_degC <= 45.0 THEN
            bArgonBackfillValveCmd := FALSE;
            bMoldCoolingBlowerCmd  := FALSE;
            iState := 90;
        END_IF;

    90: (* STATE_CYCLE_COMPLETE_DEMOLD: Atmospheric equalization, ram retract, part demold *)
        rCmdInductionPowerZ1_kW := 0.0;
        rCmdInductionPowerZ2_kW := 0.0;
        rCmdInductionPowerZ3_kW := 0.0;
        bRoughingPumpCmd        := FALSE;
        bTurboMolecularPumpCmd  := FALSE;
        bHighVacGateValveCmd    := FALSE;
        bArgonBackfillValveCmd  := FALSE;
        bMoldCoolingBlowerCmd   := FALSE;

        (* Equalize chamber to atmospheric pressure *)
        bChamberVentValveCmd := TRUE;

        (* Retract press ram *)
        rCmdPressForce_kN    := 0.0;
        rCmdRamVelocity_um_s := -20.0;

        bCycleComplete    := TRUE;
        wSystemStatusWord := 16#03FF; (* Cycle complete *)

        IF NOT bStartCycle THEN
            bChamberVentValveCmd := FALSE;
            iState := 0; (* Return to standby *)
        END_IF;

    999: (* STATE_FAILSAFE_EMERGENCY_ABORT: Controlled trip handling and energy dissipation *)
        rCmdInductionPowerZ1_kW := 0.0;
        rCmdInductionPowerZ2_kW := 0.0;
        rCmdInductionPowerZ3_kW := 0.0;
        rCmdPressForce_kN       := 0.0;
        rCmdRamVelocity_um_s    := -30.0; (* Retract ram *)
        bHighVacGateValveCmd    := FALSE;
        bTurboMolecularPumpCmd  := FALSE;
        bRoughingPumpCmd        := FALSE;
        bArgonBackfillValveCmd  := FALSE;
        bMoldCoolingBlowerCmd   := FALSE;
        bChamberVentValveCmd    := FALSE;
        wSystemStatusWord       := 16#F999;

        (* Manual Reset Sequence: Requires active acknowledgment and healthy safety circuit *)
        IF bResetAlarms AND bEStopOk AND (rCoolingWaterFlow_Lmin >= c_rMinCoolantFlow_Lmin) THEN
            wFaultCode   := 0;
            bSystemAlarm := FALSE;
            iState       := 0;
        END_IF;

END_CASE;

(* Update Status & Diagnostics *)
iSequenceStep := iState;

END_FUNCTION_BLOCK
